const server = Bun.serve({
 port: Number(Bun.env.PORT || 3000),
 async fetch(req){
   const u=new URL(req.url);
   // Explicit allowlist avoids exposing arbitrary files. Keep assets with the deployment,
   // never temporary signed provider URLs. Byte ranges support video seeking on mobile.
   const mediaFiles: Record<string, {path:string;type:string}> = {
     "/media/twanova-overview-draft.mp4": {path:"./media/twanova-overview-draft.mp4", type:"video/mp4"},
     "/media/twanova-overview-poster.jpg": {path:"./media/twanova-overview-poster.jpg", type:"image/jpeg"}
   };
   if (u.pathname.startsWith("/media/")) {
     const asset = mediaFiles[u.pathname];
     if (!asset) return new Response("Not found", {status:404});
     if (req.method !== "GET" && req.method !== "HEAD") return new Response("Method not allowed", {status:405, headers:{Allow:"GET, HEAD"}});
     const file = Bun.file(asset.path);
     if (!(await file.exists())) return new Response("Media unavailable", {status:404});
     const size = file.size;
     const headers = new Headers({"Content-Type":asset.type,"Accept-Ranges":"bytes","Cache-Control":"public, max-age=3600","Content-Length":String(size)});
     const range = req.headers.get("range");
     if (range) {
       const match = /^bytes=(\d*)-(\d*)$/.exec(range);
       if (!match || (!match[1] && !match[2])) return new Response(null,{status:416,headers:{"Content-Range":`bytes */${size}`}});
       let start = match[1] ? Number(match[1]) : Math.max(0,size-Number(match[2]));
       let end = match[1] && match[2] ? Math.min(Number(match[2]),size-1) : size-1;
       if (!Number.isSafeInteger(start) || !Number.isSafeInteger(end) || start<0 || start>=size || end<start || (!match[1] && Number(match[2])===0)) return new Response(null,{status:416,headers:{"Content-Range":`bytes */${size}`}});
       headers.set("Content-Range",`bytes ${start}-${end}/${size}`);
       headers.set("Content-Length",String(end-start+1));
       return new Response(req.method==="HEAD"?null:file.slice(start,end+1),{status:206,headers});
     }
     return new Response(req.method==="HEAD"?null:file,{headers});
   }
   const practiceScript = { "/practice-state.js": "./practice-state.js", "/practice-ui.js": "./practice-ui.js" }[u.pathname];
   if (practiceScript) {
     if (!["GET", "HEAD"].includes(req.method)) return new Response("Method not allowed", {status:405, headers:{Allow:"GET, HEAD"}});
     return new Response(req.method === "HEAD" ? null : await Bun.file(practiceScript).text(), {headers:{"content-type":"application/javascript; charset=utf-8", "x-content-type-options":"nosniff"}});
   }
   if(u.pathname==="/health") return new Response("ok");
   // Retire anonymous mock messaging without exposing or deleting earlier messages.
   // Protected operational messaging lives in the separate authenticated Hub server.
   if(u.pathname==="/api/messages" || u.pathname==="/api/messages/") {
     return Response.json({error:"Public sample messaging is unavailable. Use guided practice or log in to your real workspace.",practice:"/practice",login:"https://web-production-cd82a.up.railway.app/login.html"},{status:410,headers:{"cache-control":"no-store"}});
   }
   if(u.pathname==="/signup-demo" || u.pathname==="/signup-demo/") return new Response(await Bun.file("./signup-demo.html").text(),{headers:{"content-type":"text/html; charset=utf-8"}});
   if(u.pathname==="/pricing" || u.pathname==="/pricing/") return new Response(await Bun.file("./pricing.html").text(),{headers:{"content-type":"text/html; charset=utf-8"}});
   if(u.pathname==="/practice" || u.pathname==="/practice/") return new Response(await Bun.file("./practice.html").text(),{headers:{"content-type":"text/html; charset=utf-8"}});
   if(u.pathname==="/checkout-preview" || u.pathname==="/checkout-preview/") return new Response(await Bun.file("./checkout-preview.html").text(),{headers:{"content-type":"text/html; charset=utf-8"}});
   return new Response(render(u.pathname),{headers:{"content-type":"text/html; charset=utf-8"}});
 }
});
